+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { execFileSync } from 'node:child_process';
+import { mkdtempSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join, dirname } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import {
+  configFromAnswers, applyPatch, serializeConfig, readConfig,
+  writeConfig, writeConfigFromAnswers,
+} from '../../scaffold/setup.mjs';
+import { PROFILES } from '../profiles.mjs';
+
+const __dirname = dirname(fileURLToPath(import.meta.url));
+const templatesDir = join(__dirname, '..', '..', 'scaffold', 'templates');
+const setupMjs = join(__dirname, '..', '..', 'scaffold', 'setup.mjs');
+const CONFIG_REL = '.claude/house-standard.config.json';
+function tmp() { return mkdtempSync(join(tmpdir(), 'setup-')); }
+function baseline() {
+  const d = tmp();
+  writeConfigFromAnswers(PROFILES.full, { templatesDir, targetDir: d });
+  return d;
+}
+
+test('configFromAnswers: full profile shape', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  assert.equal(c.projectName, 'binary-prediction');
+  assert.deepEqual(c.paths, { backend: 'backend', frontend: 'frontend' });
+  assert.equal(c.frontend, true);
+  assert.deepEqual(c.modules, { frontend_design: true, codex_review: true });
+  assert.deepEqual(c.gates, {
+    codegen: { contract: 'openapi.json', regenerate: 'gen-contract', generated: ['**/_generated/**'] },
+    lint: true, specFreshness: true,
+  });
+});
+
+test('configFromAnswers: be-only profile shape', () => {
+  const c = configFromAnswers(PROFILES['be-only'], { templatesDir });
+  assert.equal(c.frontend, false);
+  assert.deepEqual(c.modules, { frontend_design: false, codex_review: false });
+});
+
+test('writeConfigFromAnswers writes canonical bytes', () => {
+  const d = tmp();
+  writeConfigFromAnswers(PROFILES.full, { templatesDir, targetDir: d });
+  const written = readFileSync(join(d, CONFIG_REL), 'utf8');
+  assert.equal(written, serializeConfig(JSON.parse(written)));
+});
+
+test('applyPatch: gates.lint true->false, siblings untouched, original unmutated', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  const next = applyPatch(c, { gates: { lint: false } });
+  assert.equal(next.gates.lint, false);
+  assert.equal(next.gates.specFreshness, true);
+  assert.deepEqual(next.gates.codegen, c.gates.codegen);
+  assert.equal(c.gates.lint, true);
+});
+
+test('applyPatch: gates.specFreshness toggle', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  assert.equal(applyPatch(c, { gates: { specFreshness: false } }).gates.specFreshness, false);
+});
+
+test('applyPatch: gates.codegen.contract change keeps siblings', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  const next = applyPatch(c, { gates: { codegen: { contract: 'api/openapi.json' } } });
+  assert.equal(next.gates.codegen.contract, 'api/openapi.json');
+  assert.equal(next.gates.codegen.regenerate, 'gen-contract');
+  assert.deepEqual(next.gates.codegen.generated, ['**/_generated/**']);
+});
+
+test('applyPatch: gates.codegen.regenerate change', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  assert.equal(applyPatch(c, { gates: { codegen: { regenerate: 'gen' } } }).gates.codegen.regenerate, 'gen');
+});
+
+test('applyPatch: gates.codegen.generated replaced wholesale', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  const next = applyPatch(c, { gates: { codegen: { generated: ['gen/**', 'api/_gen/**'] } } });
+  assert.deepEqual(next.gates.codegen.generated, ['gen/**', 'api/_gen/**']);
+});
+
+test('applyPatch: out-of-scope paths key throws with /upgrade hint', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  assert.throws(() => applyPatch(c, { paths: { backend: 'server' } }), /out of scope[\s\S]*\/upgrade/);
+});
+
+test('applyPatch: out-of-scope projectName throws', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  assert.throws(() => applyPatch(c, { projectName: 'x' }), /out of scope/);
+});
+
+test('applyPatch: wrong type throws', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  assert.throws(() => applyPatch(c, { gates: { lint: 'false' } }), /gates\.lint must be a boolean/);
+});
+
+test('applyPatch: empty contract string throws', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  assert.throws(() => applyPatch(c, { gates: { codegen: { contract: '' } } }), /non-empty string/);
+});
+
+test('applyPatch: empty generated array throws', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  assert.throws(() => applyPatch(c, { gates: { codegen: { generated: [] } } }), /non-empty array/);
+});
+
+test('applyPatch: empty or no-leaf patch throws', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  assert.throws(() => applyPatch(c, {}), /no runtime switch/);
+  assert.throws(() => applyPatch(c, { gates: { lint: {} } }), /no runtime switch/);
+});
+
+test('idempotent: patch with current value -> byte-identical file', () => {
+  const d = baseline();
+  const before = readFileSync(join(d, CONFIG_REL));
+  const c = readConfig(d);
+  writeConfig(d, applyPatch(c, { gates: { lint: c.gates.lint } }));
+  assert.ok(before.equals(readFileSync(join(d, CONFIG_REL))));
+});
+
+test('readConfig: missing file throws run /init', () => {
+  assert.throws(() => readConfig(tmp()), /run \/init first/);
+});
+
+test('readConfig: malformed JSON throws', () => {
+  const d = tmp();
+  mkdirSync(join(d, '.claude'), { recursive: true });
+  writeFileSync(join(d, CONFIG_REL), '{ not json');
+  assert.throws(() => readConfig(d), /not valid JSON/);
+});
+
+test('serializeConfig is canonical and round-trip idempotent', () => {
+  const c = configFromAnswers(PROFILES.full, { templatesDir });
+  const s = serializeConfig(c);
+  assert.equal(s, JSON.stringify(c, null, 2) + '\n');
+  assert.equal(serializeConfig(JSON.parse(s)), s);
+});
+
+test('CLI: --patch updates existing config', () => {
+  const d = baseline();
+  execFileSync('node', [setupMjs, '--target', d, '--patch', JSON.stringify({ gates: { lint: false } })]);
+  assert.equal(readConfig(d).gates.lint, false);
+});
+
+test('CLI: requires exactly one of --from-answers/--patch', () => {
+  let err;
+  try { execFileSync('node', [setupMjs, '--target', tmp()], { stdio: 'pipe' }); }
+  catch (e) { err = e; }
+  assert.ok(err, 'should exit non-zero');
+  assert.match(String(err.stderr), /exactly one/);
+});
+
+test('CLI: --patch out-of-scope key exits non-zero with /upgrade', () => {
+  const d = baseline();
+  let err;
+  try {
+    execFileSync('node', [setupMjs, '--target', d, '--patch', JSON.stringify({ paths: { backend: 'x' } })], { stdio: 'pipe' });
+  } catch (e) { err = e; }
+  assert.ok(err, 'should exit non-zero');
+  assert.match(String(err.stderr), /out of scope[\s\S]*\/upgrade/);
+});

