+// Regenerate golden snapshots. Run via `make golden-update` after intentional template changes.
+import { rmSync, mkdirSync } from 'node:fs';
+import { join, dirname } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { runInit } from './init-output.mjs';
+import { PROFILES } from './profiles.mjs';
+
+const __dirname = dirname(fileURLToPath(import.meta.url));
+const templatesDir = join(__dirname, '..', 'scaffold', 'templates');
+const manifestPath = join(__dirname, '..', 'scaffold', 'manifest.json');
+
+for (const [name, answers] of Object.entries(PROFILES)) {
+  const target = join(__dirname, 'golden', name);
+  rmSync(target, { recursive: true, force: true });
+  mkdirSync(target, { recursive: true });
+  const { written } = runInit(answers, { templatesDir, manifestPath, targetDir: target });
+  process.stdout.write(`golden/${name}: ${written.length} files\n`);
+}
